import json

# Correct grid construction
grid = []

for r in range(20):
    if r < 6:
        row = [9] + [6]*21 + [6]  # rows 0-5: left bar
    elif 10 <= r <= 15:
        row = [6]*22 + [9]  # rows 10-15: right bar
    elif r == 14:
        row = [6]*6 + [4] + [6]*15 + [8]  # row 14: dot@6->4, bar@22->8
    else:
        row = [6]*23  # middle rows: background only
    grid.append(row)

print(f"Grid: {len(grid)}x{len(grid[0])}")
print(f"Row 0[0] = {grid[0][0]}")  # should be 9 (left bar)
print(f"Row 10[22] = {grid[10][22]}")  # should be 9 (right bar)
print(f"Row 14[6] = {grid[14][6]}, row 14[22] = {grid[14][22]}")  # should be 4, 8

result = {"action": "submit", "grid": grid}
print(json.dumps(result))

